package com.bqsqwad.heartbreakhealer.feature.entertainment

internal object StoryLibraryBatch114 {
    val stories = listOf(
        StorySeries(
            id = "the_river_of_repaired_bicycles",
            title = "The River of Repaired Bicycles",
            tagline = "A riverside repair day teaches a group of students how small acts of maintenance can reconnect a neighbourhood.",
            parts = listOf(
                StoryPart(1, "The Rusty Bell", listOf("On the path beside the river, Kola found an old bicycle leaning against the community hall. Its bell was rusty, its seat was torn, and a paper tag asked whether anyone could help identify its owner.", "Kola took the tag to the hall coordinator instead of moving the bicycle. The coordinator checked the noticeboard and found that it had been left for the planned repair day.", "The event was organised by adult mechanics who would inspect every bicycle before anyone rode it. Kola signed up to help with the records and welcome table.")),
                StoryPart(2, "A List of Names", listOf("The volunteers arranged a table with forms for owners to describe their bicycles. Kola noticed that several people remembered the colour but not the brand or model.", "He suggested drawing a simple outline and marking visible details such as basket, bell, or frame colour. The mechanic reminded everyone not to publish phone numbers or home addresses on the public board.", "By midday, the team had a clear list of bicycles and the people authorised to collect them.")),
                StoryPart(3, "The First Inspection", listOf("An experienced mechanic examined each bicycle and placed it in one of three groups: ready for a basic check, needing a specialist part, or not safe to ride yet.", "Kola helped attach matching tags to the forms and bicycles. He did not attempt repairs himself; instead, he recorded what the mechanic explained.", "The group learned that a bicycle could look fine while still needing careful inspection before it was used.")),
                StoryPart(4, "A Missing Pump", listOf("The team discovered that the community hall's floor pump had disappeared from its storage corner. Without it, several simple checks would have to wait.", "Kola asked the coordinator to check the sign-out notebook. It showed that a volunteer had borrowed the pump for another approved event and would return it that afternoon.", "The delay gave the students time to prepare a clear sign explaining how visitors could request help.")),
                StoryPart(5, "The Green Bicycle", listOf("A small green bicycle belonged to a younger child who had outgrown it. The family wanted to donate it, but only after a mechanic confirmed its condition.", "The mechanic inspected the frame and components, then listed the work required before it could be passed on. The family agreed to cover the approved parts.", "Kola wrote a note for the donation register: 'Do not hand over until the final safety check is signed.'")),
                StoryPart(6, "A Day of Lessons", listOf("The repair day included a short talk about helmets, visibility, and checking a bicycle before each journey. The students listened while the adults demonstrated with a stationary bicycle.", "Kola made a simple illustrated checklist from the mechanic's approved advice. The coordinator reviewed the wording so that it did not replace a professional inspection.", "Visitors took copies home and asked when the next repair day would happen.")),
                StoryPart(7, "The Rain Arrives", listOf("Rain began before the afternoon collection time. The organisers moved the paperwork and waiting area indoors and postponed outdoor test rides.", "Some visitors were disappointed, but the mechanic explained that wet conditions made the planned checks unsuitable. The team used the time to contact owners about collection arrangements.", "Kola realised that a good event was not measured by how much it rushed to finish, but by how carefully it treated people.")),
                StoryPart(8, "A Familiar Bell", listOf("When the weather cleared the following weekend, the repaired bicycles were ready for their final checks. The rusty bell from the first bicycle had been cleaned and tested by the mechanic.", "Its owner arrived with an old photograph showing the bicycle beside a family garden. The owner recognised it immediately and thanked the volunteers for keeping the tag attached.", "Kola recorded the collection and removed the public notice so that the owner's details were no longer displayed.")),
                StoryPart(9, "The Shared Path", listOf("The community hall announced another repair day and invited experienced cyclists to lead a safe-riding information session. The students prepared a map of the riverside path using public route information.", "They marked places where the path was closed for maintenance and reminded visitors to follow official signs. The map was checked by the local parks team before printing.", "The repair project had grown into a wider effort to make the shared path easier to understand and enjoy.")),
                StoryPart(10, "A New Journey", listOf("At the end of the season, the coordinator counted the completed inspections, returned bicycles, and donated bicycles that had passed every required check.", "Kola placed the first bicycle's tag in the event scrapbook, with the owner's permission. Beside it, he wrote how the repair day had begun with one rusty bell and a simple question.", "The next event already had a waiting list of volunteers. Along the river, bicycles passed the hall in both directions, each one carrying someone toward a place they had chosen."))
            )
        )
    )
}
